function sampleMove(st,color,rnd){var b=st.board,av=st.available,ow=st.colorOwners;var list=availList(av,color);if(!list.length)return null;var first=!colorHas(b,color);var cr=CORNERS[color][0],cc=CORNERS[color][1];var att,i;if(first){for(att=0;att<40;att++){var pi=list[Math.floor(rnd()*list.length)];var oo=ORIENTS[pi];var oi=Math.floor(rnd()*oo.length);var sh=oo[oi];var k=Math.floor(rnd()*sh.length);var r=cr-sh[k][0],c=cc-sh[k][1];if(isLegal(b,av,ow,color,pi,sh,r,c))return {color:color,piece:pi,ori:oi,row:r,col:c}}for(i=0;i<list.length;i++){var p2=list[i],o2=ORIENTS[p2];for(var q=0;q<o2.length;q++){var s2=o2[q];for(var a=0;a<s2.length;a++){var r2=cr-s2[a][0],c2=cc-s2[a][1];if(isLegal(b,av,ow,color,p2,s2,r2,c2))return {color:color,piece:p2,ori:q,row:r2,col:c2}}}}return null}
var frontier=[];var seen={};for(var rr=0;rr<SIZE;rr++){for(var cc2=0;cc2<SIZE;cc2++){if(b[rr][cc2]!==color)continue;var dd=[[-1,-1],[-1,1],[1,-1],[1,1]];for(var d=0;d<4;d++){var nr=rr+dd[d][0],nc=cc2+dd[d][1];if(!inside(nr,nc)||b[nr][nc]!==-1)continue;var kk=nr+","+nc;if(!seen[kk]){seen[kk]=1;frontier.push([nr,nc])}}}}if(!frontier.length)return null;var N=frontier.length>60?60:frontier.length;for(att=0;att<N;att++){var pi2=list[Math.floor(rnd()*list.length)];var oo2=ORIENTS[pi2];var oi2=Math.floor(rnd()*oo2.length);var sh2=oo2[oi2];var tgt=frontier[Math.floor(rnd()*frontier.length)];var kk2=Math.floor(rnd()*sh2.length);var r3=tgt[0]-sh2[kk2][0],c3=tgt[1]-sh2[kk2][1];if(r3<-4||c3<-4||r3>=SIZE||c3>=SIZE)continue;if(isLegal(b,av,ow,color,pi2,sh2,r3,c3))return {color:color,piece:pi2,ori:oi2,row:r3,col:c3}}return null}
// Every legal placement covers an available corner-touching frontier square.
// Check each such anchor exactly; a missed random sample must never retire a seat.
function findMove(st,color){
 var b=st.board,allowed=[],frontier=[],first=!colorHas(b,color);
 for(var r=0;r<SIZE;r++){
  allowed[r]=[];
  for(var c=0;c<SIZE;c++){
   var ok=b[r][c]===-1&&!(r>0&&b[r-1][c]===color)&&!(r+1<SIZE&&b[r+1][c]===color)&&!(c>0&&b[r][c-1]===color)&&!(c+1<SIZE&&b[r][c+1]===color);
   allowed[r][c]=ok;
   if(ok&&(first?(r===CORNERS[color][0]&&c===CORNERS[color][1]):((r>0&&c>0&&b[r-1][c-1]===color)||(r>0&&c+1<SIZE&&b[r-1][c+1]===color)||(r+1<SIZE&&c>0&&b[r+1][c-1]===color)||(r+1<SIZE&&c+1<SIZE&&b[r+1][c+1]===color))))frontier.push([r,c]);
  }
 }
 for(var p=0;p<SHAPES.length;p++)if(st.available[color][p]){
  for(var o=0;o<ORIENTS[p].length;o++){
   var sh=ORIENTS[p][o],seen={};
   for(var f=0;f<frontier.length;f++)for(var a=0;a<sh.length;a++){
    var sr=frontier[f][0]-sh[a][0],sc=frontier[f][1]-sh[a][1];
    if(sr<0||sc<0||sr>=SIZE||sc>=SIZE)continue;
    var key=sr*SIZE+sc;if(seen[key])continue;seen[key]=true;
    var legal=true;
    for(var k=0;k<sh.length;k++){var rr=sr+sh[k][0],cc=sc+sh[k][1];if(rr>=SIZE||cc>=SIZE||!allowed[rr][cc]){legal=false;break;}}
    if(legal)return {color:color,piece:p,ori:o,row:sr,col:sc};
   }
  }
 }
 return null;
}
function pickColorFor(st,seat,rnd){var cols=[];for(var c=0;c<4;c++)if(st.colorOwners[c]===seat)cols.push(c);if(!cols.length)return -1;var start=Math.floor(rnd()*cols.length);for(var i=0;i<cols.length;i++){var col=cols[(start+i)%cols.length];var has=false;for(var p=0;p<SHAPES.length;p++)if(st.available[col][p]){has=true;break}if(has&&!st.colorDone[col])return col}for(var j=0;j<cols.length;j++){for(var p2=0;p2<SHAPES.length;p2++)if(st.available[cols[j]][p2])return cols[j]}return -1}

const gameUI = {
  reduce(message, previous) {
    const match = message.type === "ui_event" ? message.state_changed : message;
    const view = match.view || match.state;
    const click = message.event?.type === "tap" ? message.event.id : "";
    const actor = match.acting_for_player_index;
    const turn = view.currentPlayer;
    const over = match.status === "over" || view.finished;
    const active = !over && !match.replay && actor === turn &&
      match.turn_of_player_indices?.includes(actor);
    const name = seat => match.players?.[seat]?.name || "Player " + (seat + 1);
    const scene = {pieces:[], targets:[], controls:[], labels:[]};
    const offers = new Map();
    const label = (id,text,y,font_size) => scene.labels.push({id,text,x:12,y,font_size});
    const button = (id,text,move) => {
      scene.controls.push({id,kind:"button",label:text});
      if (move) offers.set(id,move);
    };
    const piece = (id,type,board,cell,extra = {}) => scene.pieces.push({
      id,type,board,position:{cell:String(cell)},actions:[],...extra
    });
    const target = (cell,move,preview) => {
      const id = "to_"+cell;
      const aria_label = KIND === "last_floe" ? "Floe " + (cell+1) :
        "Row " + (Math.floor(cell/SIZE)+1) + ", column " + (cell%SIZE+1);
      scene.targets.push({id,board:"board",position:{cell:String(cell)},label:"•",aria_label,
        ...(preview ? {preview} : {})});
      offers.set(id,move);
    };
    label("turn",over ? (view.winners || []).map(name).join(", ") || "Game over" :
      active ? name(turn)+" · Your turn" : "Waiting for "+name(turn),14,24);
    label("scores",(view.scores || []).slice(0,match.players?.length).map((score,i) =>
      name(i)+": "+score).join("  ·  "),46,16);
    const local = previous?.moveCount === match.move_count && previous.actor === actor
      ? {...previous} : {moveCount:match.move_count,actor};
    if (KIND === "last_floe") {
      const legal = view.legal || {placements:[],moves:{}};
      const sources = legal.moves || {};
      if (active && /^penguin_\d+$/.test(click || "")) {
        const source = Number(click.slice(8));
        if (sources[source]?.length) local.from = source;
      }
      label("phase",view.phase === "placement" ? "Place on a one-fish floe" :
        local.from == null ? "Select a penguin" : "Select a destination",75,17);
      for (const tile of view.tiles) {
        if (tile.removed) continue;
        piece("tile_"+tile.id,"ice","board",tile.id,{text:String(tile.fish)});
        if (tile.penguin >= 0) piece("penguin_"+tile.id,"seat"+tile.penguin,"board",tile.id,{
          text:String(tile.fish),z:2,selected:tile.id === local.from,
          actions:active && sources[tile.id]?.length ? ["tap"] : []
        });
      }
      if (active && view.phase === "placement") {
        for (const id of legal.placements) target(id,{kind:"place",id});
      } else if (active) {
        for (const to of sources[local.from] || []) target(to,{kind:"move",from:local.from,to});
        if (!Object.keys(sources).length) button("pass","No slides left — pass",{kind:"pass"});
      }
    } else {
      for (const [row,line] of view.board.entries()) {
        for (const [col,color] of line.entries()) {
          if (color >= 0) piece("square_"+row+"_"+col,"seat"+color,"board",row*SIZE+col);
        }
      }
      if (active) {
        const pick = /^pick_(\d+)_(\d+)$/.exec(click || "");
        if (pick && view.colorOwners[Number(pick[1])] === turn && view.available[Number(pick[1])][Number(pick[2])]) {
          local.color = Number(pick[1]);
          local.piece = Number(pick[2]);
          local.ori = 0;
        }
        const orientations = ORIENTS[local.piece];
        label("phase",orientations ? "Choose an outlined placement" : "Choose a piece below the board",75,17);
        if (orientations) {
          if (click === "rotate" || click === "flip") {
            const transform = click === "rotate" ? rotS : flipS;
            const next = JSON.stringify(transform(orientations[local.ori]));
            local.ori = orientations.findIndex(shape => JSON.stringify(shape) === next);
          }
          button("rotate","Rotate");
          button("flip","Flip");
          const shape = orientations[local.ori];
          for (const [r,c] of shape) piece("preview_"+r+"_"+c,"seat"+local.color,"tray",r*5+c);
          for (let row=0;row<SIZE;row++) for(let col=0;col<SIZE;col++) {
            if (isLegal(view.board,view.available,view.colorOwners,local.color,local.piece,shape,row,col)) {
              const preview = shape.map(([r,c]) => ({
                position:{cell:String((row+r)*SIZE+col+c)},color:"#90D9B3"
              }));
              target(row*SIZE+col,{color:local.color,piece:local.piece,ori:local.ori,row,col},preview);
            }
          }
        }
        const colors = ["Blue","Gold","Red","Green"];
        view.colorOwners.forEach((owner,color) => {
          if (owner !== turn) return;
          view.available[color].forEach((available,index) => {
            if (available) button("pick_"+color+"_"+index,colors[color]+" "+(index+1));
          });
        });
        button("pass","Pass",{pass:true});
      }
    }
    const result = {scene,local_state:local};
    if (offers.has(click)) result.make_move = offers.get(click);
    return result;
  }
};
